package eth.serotine.android.widget

import eth.serotine.android.R

/**
 * The rate widget's copy of [eth.serotine.ui.components.TokenIcons] as Android
 * VectorDrawables (`ic_widget_asset_<key>.xml`), since [android.widget.RemoteViews] draws
 * a drawable resource, never a Compose `ImageVector`. GENERATED by
 * scripts/gen_widget_icons.py from TokenIcons.kt; CI fails on a hand edit.
 */
object WidgetAssetIcons {

    /** The drawable resource of [key] ([eth.serotine.ui.components.TokenIcons.of]'s keys), or null for none. */
    fun of(key: String): Int? = when (key) {
        "aave" -> R.drawable.ic_widget_asset_aave
        "dai" -> R.drawable.ic_widget_asset_dai
        "eth" -> R.drawable.ic_widget_asset_eth
        "eurc" -> R.drawable.ic_widget_asset_eurc
        "eure" -> R.drawable.ic_widget_asset_eure
        "gho" -> R.drawable.ic_widget_asset_gho
        "gno" -> R.drawable.ic_widget_asset_gno
        "link" -> R.drawable.ic_widget_asset_link
        "pyusd" -> R.drawable.ic_widget_asset_pyusd
        "sdai" -> R.drawable.ic_widget_asset_sdai
        "uni" -> R.drawable.ic_widget_asset_uni
        "usdc" -> R.drawable.ic_widget_asset_usdc
        "usdt" -> R.drawable.ic_widget_asset_usdt
        "wbtc" -> R.drawable.ic_widget_asset_wbtc
        "weth" -> R.drawable.ic_widget_asset_weth
        "wxdai" -> R.drawable.ic_widget_asset_wxdai
        "xdai" -> R.drawable.ic_widget_asset_xdai
        else -> null
    }
}
